 = sessionIdOf(session);\n        if (turnId !== null) engine.endTurn(turnId);\n        return;\n      }\n      if (event?.type === 'compaction/end') {\n        /**\n         * 压缩是否失败：**只在这一处解析一次**（D2，2026-10-17 复审）。\n         *\n         * 载荷实况（DSH 0.2.0-rc.2，`dsh-compaction-basic`）：成功事件是\n         * `{ compactionId, turn, sourceCommandId? }` —— **根本没有 `error` 键**；\n         * 失败才追加 `error: errorChain(error)`，而 `errorChain` 返回的是**字符串**\n         * （`String(current)` / `current.message`）。\n         *\n         * 历史 bug：这里写的是 `event.data?.error !== true`，字符串 `!== true` 恒为 `true`\n         * ⇒ **失败路径与成功路径走完全相同的分支**（失败压缩也置标记、也写压缩前快照）；\n         * 而紧邻的上一行却用 `Boolean(event.data?.error)`（对字符串是正确的）—— 同一段两套判据。\n         *\n         * 现在统一成「键在不在」的真值判断：`undefined` / `null` 视为成功，\n         * 其余任何值（字符串、对象、布尔）一律视为失败。\n         * 注意**不能**用 `Boolean(data?.error)`：`error: ''` 是可能出现的空消息，\n         * 布尔化会把它误判成成功。\n         */\n        const failed = event.data?.error !== undefined && event.data?.error !== null;\n        const sid = sessionIdOf(session);\n        // v0.7.1（审查 #7）：无 id 时不许写压缩账（那是**写盘**）—— 在 noteCompaction 之前返回。\n        if (sid === null) return;\n        // 载荷解析**只在这一处**（上面那段注释）；标记本身折进状态里（`pendingCompaction`），\n        // 失败时清掉 —— 失败/异常结束的压缩并没有真的把水位压下来，不该抑制下一次提示。\n        engine.noteCompaction(sid, failed);\n        // v0.5.0：平台压缩后，压缩前的读数就查不到了 —— 这里追加一行「压缩账」\n        // （只对**真的压过**的那次写；失败路径不落盘，那是没走完的压缩，写它没有信息量）。\n        if (!failed) writeLedgerRow(session, sid, event);\n        return;\n      }\n      // 切模型/路由会换窗口，而官方三个字段是 last-wins、不是原子观测\n      // ⇒ 切模型后「新窗口配旧压力」。保守地解除武装，宁可晚一轮提示。\n      if (event?.type === 'request/header') {\n        const id = sessionIdOf(session);\n        if (id === null) return;\n        // v0.6.1：记下本次请求的输出预留（`config.maxTokens`）——「自动压缩点」按 DSH 的同一公式推算。\n        // v0.6.2：同一份 header 里的 provider/model 一起记下（公式直接决定于这两个值）。\n        // v0.7.0（审查 #10/#8）：**只有路由真的变了才解除武装**；头里没有 maxTokens 时\n        // 先清掉旧预留再异步回落（否则会一直用上一个模型的预留）。\n        const headerCfg = event?.data?.header?.config;\n        const routeChanged = headerCfg !== undefined && engine.setRoute(id, headerCfg) === true;\n        const reserved = headerCfg?.maxTokens;\n        if (Number.isFinite(reserved)) engine.setReserve(id, reserved);\n        else {\n          engine.clearReserve(id);\n          resolveDefaultReserve(headerCfg?.provider, headerCfg?.model, id);\n        }\n        if (routeChanged && engine.resetArming(id)) {\n          info(makeT(localeOf(session, id))('log.arming.reset', { name, session: id }));\n        }\n      }\n      // v0.7.0（审查 P1-3）：`model/selection` 的载荷是 `{provider, model, reasoningEffort}`，\n      // **没有 header**（旧实现读 `data.header.config` 永远读不到）。它的价值是「立刻」更新路由，\n      // 不必等下一次请求；预留由下一次 `request/header` 补。\n      if (event?.type === 'model/selection') {\n        const id = sessionIdOf(session);\n        if (id === null) return;\n        const selection = event?.data;\n        const routeChanged = selection !== null && typeof selection === 'object' && engine.setRoute(id, selection) === true;\n        if (routeChanged) {\n          engine.clearReserve(id);\n          resolveDefaultReserve(selection.provider, selection.model, id);\n          if (engine.resetArming(id)) {\n            info(makeT(localeOf(session, id))('log.arming.reset', { name, session: id }));\n          }\n        }\n      }\n      // v0.6.2：智能体预设（用于环境指纹；不参与判定）\n      if (event?.type === 'agent-preset/selected') {\n        const preset = event?.data?.agentPreset;\n        const presetId = sessionIdOf(session);\n        if (typeof preset === 'string' && preset !== '' && presetId !== null) engine.setPreset(presetId, preset);\n        return;\n      }\n    } catch (error) {\n      warn(bootT()('log.sessionEvent.exception', { name, error: error?.message ?? error }));\n    }\n  });\n\n  // —— 会话创建（新建**或**从存储恢复，二者都是这一个事件）。\n  // `session/created` 是同步 emit：抛出会否决并回滚创建，所以这里必须什么都吞掉。\n  ctx.on('session/created', (session) => {\n    try {\n      refreshConfig();\n      const projections = ctx.get('sessionProjections');\n      if (projections === undefined || typeof projections.snapshot !== 'function') return;\n      const id = sessionIdOf(session);\n      // v0.7.1（审查 #7）：`session/created` 是**同步 emit**，宿主不隔离同步抛错\n      // ⇒ 这里只 `return`、绝不 `throw`（否则会回滚创建、还连坐同轮其它插件）。\n      if (id === null) return;\n      // v0.6.1：恢复的会话可能已经有一条 request/header —— 能读就读，读不到等下一次请求。\n      try {\n        const header = session?.requestHeader?.();\n        const reserved = header?.config?.maxTokens;\n        if (Number.isFinite(reserved)) engine.setReserve(id, reserved);\n        else resolveDefaultReserve(header?.config?.provider, header?.config?.model, id);\n        if (header?.config !== undefined) engine.setRoute(id, header.config);\n      } catch {\n        /* 读不到不是故障，只是「自动压缩点」暂时显示不出来 */\n      }\n      const snap = projections.snapshot(session, [...MATERIAL_KEYS]);\n      for (const [k, v] of Object.entries(snap?.values ?? {})) noteMaterial(id, k, v, session);\n      const hit = engine.onResume(id, snap?.values?.[KEY], { locale: localeOf(session, id) });\n      if (hit !== null) {\n        logHit(hit);\n      }\n      // 点进一个**已经很高**的历史会话：同一时刻就该把交接草稿备好（§10.4：会话打开才是「跨会话」的实质）\n      lastPressure.set(id, snap?.values?.[KEY]);\n      lastSession.set(id, session);\n      maybeDraftHandover(session, id, snap?.values?.[KEY]);\n    } catch (error) {\n      warn(bootT()('log.resume.exception', { name, error: error?.message ?? error }));\n    }\n  });\n  // —— 会话销毁（v0.6.0）：清掉按会话的四个 Map + 引擎状态/回执。\n  // daemon 是常驻的，不清就是「打开过的会话一个都不释放」——与「零税」的定位相反。\n  ctx.on('session/disposed', (session) => {\n    try {\n      const id = sessionIdOf(session);\n      // v0.7.1（审查 #7）：没有 id 就没有可清的键 —— 共享桶已不存在，这个特判可以退化成 null 守卫。\n      if (id === null) return;\n      material.delete(id);\n      lastPressure.delete(id);\n      lastSession.delete(id);\n      recentReadings.delete(id);\n      draftState.lastRatio.delete(id);\n      engine.forget(id);\n    } catch (error) {\n    